    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_exponential_net_ffi_fn_free_enetaccesspolicy(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_exponential_net_ffi_fn_clone_enetaccesspolicy(handle, status)
        }
    }

    override fun `allow`(`peer`: kotlin.String, `alpn`: kotlin.String): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_exponential_net_ffi_fn_method_enetaccesspolicy_allow(
        it,
        FfiConverterString.lower(`peer`),FfiConverterString.lower(`alpn`),_status)
}
    }
    )
    }
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceEnetAccessPolicy {
    internal object `allow`: UniffiCallbackInterfaceEnetAccessPolicyMethod0 {
        override fun callback(`uniffiHandle`: Long,`peer`: RustBuffer.ByValue,`alpn`: RustBuffer.ByValue,`uniffiOutReturn`: ByteByReference,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeEnetAccessPolicy.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`allow`(
                    FfiConverterString.lift(`peer`),
                    FfiConverterString.lift(`alpn`),
                )
            }
            val writeReturn = { value: kotlin.Boolean -> uniffiOutReturn.setValue(FfiConverterBoolean.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeEnetAccessPolicy.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeEnetAccessPolicy.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceEnetAccessPolicy.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `allow`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_exponential_net_ffi_fn_init_callback_vtable_enetaccesspolicy(vtable)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeEnetAccessPolicy: FfiConverter<EnetAccessPolicy, Long> {
    internal val handleMap = UniffiHandleMap<EnetAccessPolicy>()

    override fun lower(value: EnetAccessPolicy): Long {
        if (value is EnetAccessPolicyImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): EnetAccessPolicy {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return EnetAccessPolicyImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): EnetAccessPolicy {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: EnetAccessPolicy) = 8UL

    override fun write(value: EnetAccessPolicy, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


