/**
 * @suppress
 */
public object FfiConverterTypeEnetNode: FfiConverter<EnetNode, Long> {
    override fun lower(value: EnetNode): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): EnetNode {
        return EnetNode(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): EnetNode {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: EnetNode) = 8UL

    override fun write(value: EnetNode, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



