sealed class EnetException: kotlin.Exception() {
    
    /**
     * Bad input from the host (a malformed id, ticket, key, size).
     */
    class Invalid(
        
        val `reason`: kotlin.String
        ) : EnetException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * Binding the endpoint / opening the store failed.
     */
    class Bind(
        
        val `reason`: kotlin.String
        ) : EnetException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * Could not reach the peer (offline, no address, timeout).
     */
    class Connect(
        
        val `reason`: kotlin.String
        ) : EnetException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The peer's access policy refused this node.
     */
    class Refused(
        
        val `reason`: kotlin.String
        ) : EnetException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * A record or payload failed authentication.
     */
    class Crypto(
        
        val `reason`: kotlin.String
        ) : EnetException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class NotFound(
        
        val `reason`: kotlin.String
        ) : EnetException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * Any other transport failure.
     */
    class Transport(
        
        val `reason`: kotlin.String
        ) : EnetException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The node is shut down.
     */
    class Closed(
        
        val `reason`: kotlin.String
        ) : EnetException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * eNet panicked inside this call; the node stays usable.
     */
    class Panic(
        
        val `reason`: kotlin.String
        ) : EnetException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<EnetException> {
        override fun lift(error_buf: RustBuffer.ByValue): EnetException = FfiConverterTypeEnetError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeEnetError : FfiConverterRustBuffer<EnetException> {
    override fun read(buf: ByteBuffer): EnetException {
        

        return when(buf.getInt()) {
            1 -> EnetException.Invalid(
                FfiConverterString.read(buf),
                )
            2 -> EnetException.Bind(
                FfiConverterString.read(buf),
                )
            3 -> EnetException.Connect(
                FfiConverterString.read(buf),
                )
            4 -> EnetException.Refused(
                FfiConverterString.read(buf),
                )
            5 -> EnetException.Crypto(
                FfiConverterString.read(buf),
                )
            6 -> EnetException.NotFound(
                FfiConverterString.read(buf),
                )
            7 -> EnetException.Transport(
                FfiConverterString.read(buf),
                )
            8 -> EnetException.Closed(
                FfiConverterString.read(buf),
                )
            9 -> EnetException.Panic(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EnetException): ULong {
        return when(value) {
            is EnetException.Invalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is EnetException.Bind -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is EnetException.Connect -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is EnetException.Refused -> (
