/**
 * @suppress
 */
public object FfiConverterTypeEnetEvent : FfiConverterRustBuffer<EnetEvent>{
    override fun read(buf: ByteBuffer): EnetEvent {
        return when(buf.getInt()) {
            1 -> EnetEvent.Chat(
                FfiConverterString.read(buf),
                FfiConverterTypeEnetChatMessage.read(buf),
                )
            2 -> EnetEvent.Record(
                FfiConverterTypeEnetRecord.read(buf),
                )
            3 -> EnetEvent.CallIncoming(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> EnetEvent.CallAccepted(
                FfiConverterULong.read(buf),
                )
            5 -> EnetEvent.CallFrame(
                FfiConverterULong.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterByteArray.read(buf),
                )
            6 -> EnetEvent.CallEnded(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            7 -> EnetEvent.PeerRefused(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EnetEvent) = when(value) {
        is EnetEvent.Chat -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`from`)
                + FfiConverterTypeEnetChatMessage.allocationSize(value.`message`)
            )
        }
        is EnetEvent.Record -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeEnetRecord.allocationSize(value.`record`)
            )
        }
        is EnetEvent.CallIncoming -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`call`)
                + FfiConverterString.allocationSize(value.`from`)
            )
        }
        is EnetEvent.CallAccepted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`call`)
            )
        }
        is EnetEvent.CallFrame -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`call`)
                + FfiConverterUInt.allocationSize(value.`seq`)
                + FfiConverterByteArray.allocationSize(value.`data`)
            )
        }
        is EnetEvent.CallEnded -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`call`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is EnetEvent.PeerRefused -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peer`)
                + FfiConverterString.allocationSize(value.`alpn`)
            )
        }
    }

    override fun write(value: EnetEvent, buf: ByteBuffer) {
        when(value) {
            is EnetEvent.Chat -> {
                buf.putInt(1)
                FfiConverterString.write(value.`from`, buf)
                FfiConverterTypeEnetChatMessage.write(value.`message`, buf)
                Unit
            }
            is EnetEvent.Record -> {
                buf.putInt(2)
                FfiConverterTypeEnetRecord.write(value.`record`, buf)
                Unit
            }
            is EnetEvent.CallIncoming -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`call`, buf)
                FfiConverterString.write(value.`from`, buf)
                Unit
            }
            is EnetEvent.CallAccepted -> {
                buf.putInt(4)
                FfiConverterULong.write(value.`call`, buf)
                Unit
            }
            is EnetEvent.CallFrame -> {
                buf.putInt(5)
                FfiConverterULong.write(value.`call`, buf)
                FfiConverterUInt.write(value.`seq`, buf)
                FfiConverterByteArray.write(value.`data`, buf)
                Unit
            }
            is EnetEvent.CallEnded -> {
                buf.putInt(6)
                FfiConverterULong.write(value.`call`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is EnetEvent.PeerRefused -> {
                buf.putInt(7)
                FfiConverterString.write(value.`peer`, buf)
                FfiConverterString.write(value.`alpn`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
